// ===== ULTRA ROBUSTO: funciona con cualquier versión de N8N =====
const input = $json.body || $json || {};
const evento = input.evento || 'desconocido';
const datos = input.datos || {};
const resumen = input.resumen || {};
const timestamp = input.timestamp || new Date().toISOString();

let emails = [];

// ========== EMAIL DE BACKUP (SIEMPRE) ==========
let backupAsunto = 'AgroTech - Movimiento registrado';
let backupHtml = '';

if (evento === 'gasto_registrado') {
  backupAsunto = '💸 Gasto registrado - ' + (datos.concepto || 'Sin concepto');
  backupHtml = '<h2>💸 Gasto Registrado</h2><table style="border-collapse:collapse;font-family:Arial;width:100%;"><tr style="background:#ef4444;color:white;"><th style="padding:10px;">Campo</th><th style="padding:10px;">Valor</th></tr><tr><td style="padding:8px;border:1px solid #ddd;">Fecha</td><td style="padding:8px;border:1px solid #ddd;">' + timestamp + '</td></tr><tr><td style="padding:8px;border:1px solid #ddd;">Cuartel</td><td style="padding:8px;border:1px solid #ddd;">' + (datos.loteId || '-') + '</td></tr><tr><td style="padding:8px;border:1px solid #ddd;">Concepto</td><td style="padding:8px;border:1px solid #ddd;">' + (datos.concepto || '-') + '</td></tr><tr><td style="padding:8px;border:1px solid #ddd;">Monto</td><td style="padding:8px;border:1px solid #ddd;"><strong>$' + (datos.monto || 0).toLocaleString('es-AR') + '</strong></td></tr><tr><td style="padding:8px;border:1px solid #ddd;">Estado</td><td style="padding:8px;border:1px solid #ddd;">' + (datos.estado || '-') + '</td></tr></table><p><strong>Saldo Neto:</strong> $' + (resumen.saldoNeto || 0).toLocaleString('es-AR') + '</p>';
} else if (evento === 'ingreso_registrado') {
  backupAsunto = '🏦 Ingreso registrado - ' + (datos.origen || 'Sin origen');
  backupHtml = '<h2>🏦 Ingreso Registrado</h2><table style="border-collapse:collapse;font-family:Arial;width:100%;"><tr style="background:#10b981;color:white;"><th style="padding:10px;">Campo</th><th style="padding:10px;">Valor</th></tr><tr><td style="padding:8px;border:1px solid #ddd;">Fecha</td><td style="padding:8px;border:1px solid #ddd;">' + timestamp + '</td></tr><tr><td style="padding:8px;border:1px solid #ddd;">Origen</td><td style="padding:8px;border:1px solid #ddd;">' + (datos.origen || '-') + '</td></tr><tr><td style="padding:8px;border:1px solid #ddd;">Tipo Pago</td><td style="padding:8px;border:1px solid #ddd;">' + (datos.tipo || '-') + '</td></tr><tr><td style="padding:8px;border:1px solid #ddd;">Monto</td><td style="padding:8px;border:1px solid #ddd;"><strong>$' + (datos.monto || 0).toLocaleString('es-AR') + '</strong></td></tr><tr><td style="padding:8px;border:1px solid #ddd;">Estado</td><td style="padding:8px;border:1px solid #ddd;">' + (datos.estado || '-') + '</td></tr></table><p><strong>Saldo Neto:</strong> $' + (resumen.saldoNeto || 0).toLocaleString('es-AR') + '</p>';
} else if (evento === 'inversion_registrada') {
  backupAsunto = '📈 Inversión registrada - ' + (datos.ticker || 'Sin ticker');
  backupHtml = '<h2>📈 Inversión Registrada</h2><table style="border-collapse:collapse;font-family:Arial;width:100%;"><tr style="background:#3b82f6;color:white;"><th style="padding:10px;">Campo</th><th style="padding:10px;">Valor</th></tr><tr><td style="padding:8px;border:1px solid #ddd;">Fecha</td><td style="padding:8px;border:1px solid #ddd;">' + timestamp + '</td></tr><tr><td style="padding:8px;border:1px solid #ddd;">Ticker</td><td style="padding:8px;border:1px solid #ddd;">' + (datos.ticker || '-') + '</td></tr><tr><td style="padding:8px;border:1px solid #ddd;">Monto</td><td style="padding:8px;border:1px solid #ddd;"><strong>$' + (datos.monto || 0).toLocaleString('es-AR') + '</strong></td></tr></table><p><strong>Saldo Neto:</strong> $' + (resumen.saldoNeto || 0).toLocaleString('es-AR') + '</p>';
} else if (evento === 'cheques_pendientes') {
  const cheques = datos.cheques || [];
  const total = cheques.reduce((s, c) => s + (c.monto || 0), 0);
  backupAsunto = '📅 Cheques sincronizados - AgroTech';
  backupHtml = '<h2>📅 Cheques Pendientes</h2><p>Tenés <strong>' + cheques.length + '</strong> cheque(s) en cartera:</p><table style="border-collapse:collapse;font-family:Arial;width:100%;"><tr style="background:#f59e0b;color:white;"><th style="padding:10px;">#</th><th style="padding:10px;">Tipo</th><th style="padding:10px;">Monto</th><th style="padding:10px;">Vencimiento</th></tr>' + cheques.map((c, i) => '<tr><td style="padding:8px;border:1px solid #ddd;">' + (i+1) + '</td><td style="padding:8px;border:1px solid #ddd;">' + (c.tipo === 'echeq' ? 'Echeq' : 'Físico') + '</td><td style="padding:8px;border:1px solid #ddd;">$' + (c.monto || 0).toLocaleString('es-AR') + '</td><td style="padding:8px;border:1px solid #ddd;">' + (c.fecha ? c.fecha.split('-').reverse().join('/') : '-') + '</td></tr>').join('') + '</table><p><strong>Total:</strong> $' + total.toLocaleString('es-AR') + '</p>';
} else if (evento === 'test_conexion') {
  backupAsunto = '🧪 Prueba de conexión - AgroTech';
  backupHtml = '<h2>🧪 Prueba de Conexión Exitosa</h2><p>AgroTech se conectó correctamente con N8N.</p><pre>' + JSON.stringify(datos, null, 2) + '</pre>';
} else {
  backupAsunto = '📋 Evento: ' + evento;
  backupHtml = '<h2>Evento registrado</h2><pre>' + JSON.stringify(datos, null, 2) + '</pre>';
}

emails.push({ tipo: 'backup', asunto: backupAsunto, html: backupHtml });

// ========== EMAIL DE ALERTA (SOLO SI APLICA) ==========

// Alerta de déficit
if ((evento === 'gasto_registrado' || evento === 'test_conexion') && resumen.saldoNeto < 0) {
  emails.push({
    tipo: 'alerta',
    asunto: '🚨 ALERTA: Caja en déficit - AgroTech',
    html: '<h2>🚨 Alerta AgroTech</h2><p>La caja quedó en <strong>DÉFICIT</strong>.</p><ul><li>💰 Saldo: <strong>-$' + Math.abs(resumen.saldoNeto).toLocaleString('es-AR') + '</strong></li><li>📊 Ingresos: $' + (resumen.totalIngresos || 0).toLocaleString('es-AR') + '</li><li>📉 Gastos: $' + (resumen.totalGastos || 0).toLocaleString('es-AR') + '</li></ul><p>Revisá los gastos programados en la app.</p>'
  });
}

// Alerta de ingreso grande
if (evento === 'ingreso_registrado' && datos.monto > 500000) {
  emails.push({
    tipo: 'alerta',
    asunto: '💰 Ingreso grande - AgroTech',
    html: '<h2>💰 Ingreso Grande</h2><ul><li>📍 Origen: <strong>' + (datos.origen || '-') + '</strong></li><li>💵 Monto: <strong>$' + (datos.monto || 0).toLocaleString('es-AR') + '</strong></li><li>🏦 Tipo: ' + (datos.tipo || '-') + '</li></ul><p>Saldo neto: $' + (resumen.saldoNeto || 0).toLocaleString('es-AR') + '</p>'
  });
}

// Alerta de cheques próximos
if (evento === 'cheques_pendientes' && datos.cheques && datos.cheques.length > 0) {
  const hoy = new Date();
  const proximos = datos.cheques.filter(c => {
    if (!c.fecha) return false;
    const f = new Date(c.fecha + 'T00:00:00');
    const diff = (f - hoy) / (1000 * 60 * 60 * 24);
    return diff >= -1 && diff <= 5 && c.estado === 'normal' && !c.descontado;
  });
  if (proximos.length > 0) {
    const total = proximos.reduce((s, c) => s + (c.monto || 0), 0);
    emails.push({
      tipo: 'alerta',
      asunto: '📅 Recordatorio: Cheques por cobrar - AgroTech',
      html: '<h2>📅 Recordatorio</h2><p>Tenés <strong>' + proximos.length + '</strong> cheque(s) por cobrar pronto:</p><table style="border-collapse:collapse;font-family:Arial;width:100%;"><tr style="background:#047857;color:white;"><th style="padding:10px;">#</th><th style="padding:10px;">Tipo</th><th style="padding:10px;">Monto</th><th style="padding:10px;">Vencimiento</th></tr>' + proximos.map((c, i) => '<tr><td style="padding:8px;border:1px solid #ddd;">' + (i+1) + '</td><td style="padding:8px;border:1px solid #ddd;">' + (c.tipo === 'echeq' ? 'Echeq' : 'Físico') + '</td><td style="padding:8px;border:1px solid #ddd;">$' + (c.monto || 0).toLocaleString('es-AR') + '</td><td style="padding:8px;border:1px solid #ddd;">' + (c.fecha ? c.fecha.split('-').reverse().join('/') : '-') + '</td></tr>').join('') + '</table><p><strong>Total pendiente: $' + total.toLocaleString('es-AR') + '</strong></p>'
    });
  }
}

return emails.map(e => ({ json: e }));
